inline void fft512_forward(float* real, float* imag) {
    constexpr uint16_t N = 512;

    // Bit-reversal permutation.
    uint16_t j = 0;
    for (uint16_t i = 1; i < N; ++i) {
        uint16_t bit = N >> 1;
        while (j & bit) {
            j ^= bit;
            bit >>= 1;
        }
        j ^= bit;
        if (i < j) {
            std::swap(real[i], real[j]);
            std::swap(imag[i], imag[j]);
        }
    }

    // Unnormalized radix-2 DFT, matching numpy/librosa FFT scaling.
    for (uint16_t len = 2; len <= N; len <<= 1) {
        const uint16_t half = len >> 1;
        const uint16_t twiddle_step = N / len;
        for (uint16_t base = 0; base < N; base += len) {
            for (uint16_t k = 0; k < half; ++k) {
                const uint16_t tw = k * twiddle_step;
                const float wr = FFT_TWIDDLE_COS[tw];
                const float wi = FFT_TWIDDLE_SIN[tw];
                const uint16_t even = base + k;
                const uint16_t odd = even + half;

                const float tr = wr * real[odd] - wi * imag[odd];
                const float ti = wr * imag[odd] + wi * real[odd];
                const float ur = real[even];
                const float ui = imag[even];

                real[even] = ur + tr;
                imag[even] = ui + ti;
                real[odd] = ur - tr;
                imag[odd] = ui - ti;
            }
        }
    }
}
